SELECT id, merchant, SUBSTRING(txn_type, 1, 4) AS txn_type_prefix
FROM transactions
WHERE amount >= 2800;

SELECT started_at, LOWER(browser) AS browser_lower
FROM sessions
WHERE country = 'US';

SELECT order_id, status, TRIM(status) AS clean_status
FROM payments
WHERE method <> 'paypal';

SELECT dept_id, email, CONCAT(full_name, ' - ', email) AS full_name_email
FROM employees
WHERE job_title = 'Manager';

SELECT *, LENGTH(dept_name) AS dept_name_length
FROM departments
WHERE dept_name IN ('Sales', 'HR');

select id, page, count(*) over (partition by page) as page_count
from web_events
order by id;

select customer_id, num_orders, avg_discount
from (
    select customer_id, count(*) as num_orders, avg(discount) as avg_discount
    from orders
    group by customer_id
) as t
where avg_discount < 0.27;

SELECT status, amount, GREATEST(discount, shipping_fee) AS greatest_discount_shipping_fee
FROM orders
ORDER BY amount DESC;

SELECT a.id, a.status, a.account_type
FROM accounts a
WHERE a.customer_id IS NULL AND a.customer_id IN (SELECT id FROM customers WHERE city <> 'London');

SELECT payments.id, payments.amount, payments.paid_at
FROM payments
WHERE payments.order_id IS NULL AND payments.order_id IN (SELECT id FROM orders WHERE store_id IS NOT NULL);

SELECT * FROM (SELECT country, city, rating FROM suppliers WHERE supplier_name LIKE '%Pac%')
PIVOT (MAX(rating) FOR city IN ('Singapore', 'Chiang Mai', 'New York'))
ORDER BY country;

SELECT * FROM (SELECT city, region, sqft FROM stores WHERE LOWER(store_name) LIKE '%iam%')
PIVOT (MAX(sqft) FOR region IN ('West', 'North', 'East', 'South'))
ORDER BY city;

SELECT p.id, p.order_id, p.amount
FROM payments p
WHERE p.method IN ('bank_transfer', 'promptpay', 'card') AND p.order_id IN (SELECT id FROM orders WHERE status = 'COMPLETED');

SELECT id, country, COUNT(*) OVER (PARTITION BY country) country_count
FROM customers
WHERE age <= 66;

select id, category, count(*) over (partition by category) as category_count
from products
where brand <> 'Acme';

SELECT *
FROM transactions
WHERE amount <= 2500 AND (amount > 1200 OR txn_type IN ('FEE', 'CREDIT'));

select p.id, p.price, p.product_name
from products p
where p.launch_date < '2025-10-01' and p.id in (select product_id from store_sales where product_id in (2, 5, 7, 9));

SELECT *, UPPER(country) AS country_upper, COALESCE(browser, 'Unknown') AS browser_filled
FROM sessions
WHERE country = 'US';

SELECT COUNT(monthly_fee) AS monthly_fee_count, ROUND(AVG(monthly_fee), 2) AS avg_monthly_fee, MAX(start_date) AS latest_start_date
FROM subscriptions
WHERE monthly_fee <= 170 AND start_date BETWEEN '2023-09-01' AND '2023-09-18';
